import React, { useState } from 'react';
import { useAuth } from '../../hooks/useAuth';
import type { UserRole } from '../../types';

const RegisterPage: React.FC = () => {
  const { register } = useAuth();
  const [role, setRole] = useState<UserRole>('student');
  const [form, setForm] = useState({ username:'', email:'', password:'', confirm:'' });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const f = (k: keyof typeof form) => (e: React.ChangeEvent<HTMLInputElement>) => setForm(p => ({ ...p, [k]: e.target.value }));

  const handleSubmit = async () => {
    if (!form.username || !form.email || !form.password) { setError('Vui lòng nhập đầy đủ thông tin'); return; }
    if (form.password.length < 6) { setError('Mật khẩu phải có ít nhất 6 ký tự'); return; }
    if (form.password !== form.confirm) { setError('Mật khẩu xác nhận không khớp'); return; }
    setLoading(true); setError('');
    try { await register({ username: form.username, email: form.email, password: form.password, role }); }
    catch (e) { 
      const err = e as { response?: { data?: { message?: string } } };
      setError(err?.response?.data?.message || 'Đăng ký thất bại, vui lòng thử lại'); 
    }
    finally { setLoading(false); }
  };

  const inp: React.CSSProperties = { width:'100%', height:46, border:'1.5px solid var(--border)', borderRadius:8, padding:'0 14px', background:'var(--bg)', color:'var(--text)', fontSize:15, outline:'none', fontFamily:'inherit', transition:'all .2s' };
  const focus = (e: React.FocusEvent<HTMLInputElement>) => { e.target.style.borderColor='var(--pri)'; e.target.style.boxShadow='0 0 0 3px rgba(79,140,255,.1)'; };
  const blur = (e: React.FocusEvent<HTMLInputElement>) => { e.target.style.borderColor='var(--border)'; e.target.style.boxShadow=''; };

  const ROLES: { value: UserRole; icon: string; label: string; desc: string }[] = [
    { value:'student', icon:'🎓', label:'Sinh viên', desc:'Đặt câu hỏi, học hỏi' },
    { value:'lecturer', icon:'👨‍🏫', label:'Giảng viên', desc:'Chia sẻ kiến thức' },
  ];

  return (
    <div style={{ minHeight:'100vh', display:'flex', alignItems:'center', justifyContent:'center', padding:24, background:'linear-gradient(135deg,rgba(79,140,255,.06),rgba(123,97,255,.06))' }}>
      <div style={{ width:'100%', maxWidth:460, background:'var(--surface)', border:'1px solid var(--border)', borderRadius:20, padding:40, boxShadow:'var(--shadow-lg)' }}>
        <div style={{ textAlign:'center', marginBottom:28 }}>
          <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:800, fontSize:26, background:'linear-gradient(135deg,var(--pri),var(--sec))', WebkitBackgroundClip:'text', WebkitTextFillColor:'transparent', backgroundClip:'text', marginBottom:8 }}>📚 Tạo tài khoản</div>
          <div style={{ color:'var(--muted)', fontSize:15 }}>Tham gia cộng đồng học tập</div>
        </div>

        {error && (
          <div style={{ background:'rgba(239,68,68,.08)', border:'1px solid rgba(239,68,68,.3)', borderRadius:8, padding:'10px 14px', fontSize:14, color:'var(--danger)', marginBottom:16 }}>⚠️ {error}</div>
        )}

        {/* Role picker */}
        <div style={{ marginBottom:20 }}>
          <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:10 }}>Bạn là</label>
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:10 }}>
            {ROLES.map(r => (
              <div key={r.value} onClick={() => setRole(r.value)}
                style={{ border:`2px solid ${role===r.value?'var(--pri)':'var(--border)'}`, borderRadius:10, padding:14, textAlign:'center', cursor:'pointer', background:role===r.value?'rgba(79,140,255,.06)':'transparent', transition:'all .2s' }}>
                <div style={{ fontSize:28, marginBottom:6 }}>{r.icon}</div>
                <div style={{ fontWeight:600, fontSize:14 }}>{r.label}</div>
                <div style={{ fontSize:12, color:'var(--muted)', marginTop:3 }}>{r.desc}</div>
              </div>
            ))}
          </div>
        </div>

        {[
          { key:'username', label:'Tên đăng nhập', placeholder:'sv_tenminhban', type:'text' },
          { key:'email', label:'Email', placeholder:'email@student.edu.vn', type:'email' },
          { key:'password', label:'Mật khẩu', placeholder:'Ít nhất 6 ký tự', type:'password' },
          { key:'confirm', label:'Xác nhận mật khẩu', placeholder:'Nhập lại mật khẩu', type:'password' },
        ].map(field => (
          <div key={field.key} style={{ marginBottom:16 }}>
            <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:6 }}>{field.label}</label>
            <input type={field.type} value={(form)[field.key as keyof typeof form]} onChange={f(field.key as keyof typeof form)} placeholder={field.placeholder} style={inp} onFocus={focus} onBlur={blur} />
          </div>
        ))}

        <button onClick={handleSubmit} disabled={loading} style={{ width:'100%', height:48, borderRadius:24, border:'none', background:'linear-gradient(135deg,var(--pri),var(--sec))', color:'#fff', cursor:loading?'not-allowed':'pointer', fontSize:16, fontWeight:600, fontFamily:'inherit', opacity:loading?.75:1, marginTop:8 }}>
          {loading ? 'Đang tạo tài khoản...' : 'Tạo tài khoản →'}
        </button>

        <div style={{ textAlign:'center', fontSize:14, color:'var(--muted)', marginTop:20 }}>
          Đã có tài khoản?{' '}
          <span onClick={() => history.push('/auth/login')} style={{ color:'var(--pri)', fontWeight:600, cursor:'pointer' }}>Đăng nhập</span>
        </div>
      </div>
    </div>
  );
};

export default RegisterPage;

admin/index.__content:
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'umi';
import UserAvatar from '../../components/common/UserAvatar';
import RoleBadge from '../../components/common/RoleBadge';
import TagBadge from '../../components/common/TagBadge';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import { adminService } from '../../services/adminService';
import { addToast } from '../../utils/toast';
import { timeAgo } from '../../utils/helpers';
import type { User, Post, Tag, AdminStats } from '../../types';

interface Props { currentUser: User; }

type MenuKey = 'dashboard' | 'users' | 'posts' | 'tags';

const MENU: { key: MenuKey; icon: string; label: string }[] = [
  { key:'dashboard', icon:'📊', label:'Dashboard' },
  { key:'users', icon:'👥', label:'Người dùng' },
  { key:'posts', icon:'📝', label:'Bài viết' },
  { key:'tags', icon:'🏷️', label:'Tags' },
];

const AdminPage: React.FC<Props> = ({ currentUser }) => {
  const navigate = useNavigate();
  const [menu, setMenu] = useState<MenuKey>('dashboard');
  const [stats, setStats] = useState<AdminStats | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [posts, setPosts] = useState<Post[]>([]);
  const [tags, setTags] = useState<Tag[]>([]);
  const [loading, setLoading] = useState(false);
  const [editUser, setEditUser] = useState<User | null>(null);
  const [showAddUser, setShowAddUser] = useState(false);
  const [showAddTag, setShowAddTag] = useState(false);
  const [newUser, setNewUser] = useState({ name:'', email:'', role:'student', password:'' });
  const [newTag, setNewTag] = useState({ name:'', color:'#4f8cff', description:'' });

  if (currentUser.role !== 'admin') { navigate('/'); return null; }

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      try {
        const [st, us, ps] = await Promise.all([
          adminService.getStats(),
          adminService.getUsers(),
          adminService.getPosts(),
        ]);
        setStats(st);
        setUsers(us);
        setPosts(ps);
      } catch { /* use empty */ }
      finally { setLoading(false); }
    };
    load();
  }, []);

  const handleToggleLock = async (id: string) => {
    try { await adminService.lockUser(id); setUsers(p => p.map(u => u.id===id?{...u,status: u.status === 'active' ? 'locked' : 'active'}:u)); addToast('Đã cập nhật trạng thái!','success'); }
    catch { addToast('Lỗi cập nhật','error'); }
  };
  const handleResetPw = async (id: string) => {
    try { await adminService.resetPassword(id); addToast('Mật khẩu mới đã được gửi email','success'); }
    catch { addToast('Lỗi reset mật khẩu','error'); }
  };
  const handleDeleteUser = async (id: string) => {
    if (!window.confirm('Xóa người dùng này?')) return;
    try { await adminService.deleteUser(id); setUsers(p => p.filter(u => u.id!==id)); addToast('Đã xóa người dùng','success'); }
    catch { addToast('Lỗi xóa','error'); }
  };
  const handleDeletePost = async (id: string) => {
    if (!window.confirm('Xóa bài viết này?')) return;
    try { await adminService.deletePost(id); setPosts(p => p.filter(x => x.id!==id)); addToast('Đã xóa bài viết','success'); }
    catch { addToast('Lỗi xóa','error'); }
  };
  const handleSaveUser = async () => {
    if (!editUser) return;
    try { await adminService.updateUser(editUser.id, editUser); setUsers(p => p.map(u => u.id===editUser.id?editUser:u)); setEditUser(null); addToast('Đã cập nhật!','success'); }
    catch { addToast('Lỗi cập nhật','error'); }
  };
  const handleAddUser = async () => {
    if (!newUser.name||!newUser.email||!newUser.password) { addToast('Vui lòng nhập đủ thông tin','error'); return; }
    try {
      const u = await adminService.createUser(newUser as any);
      setUsers(p => [...p, u]); setShowAddUser(false); setNewUser({name:'',email:'',role:'student',password:''}); addToast('Đã thêm người dùng!','success');
    } catch { addToast('Lỗi thêm người dùng','error'); }
  };

  const inp: React.CSSProperties = { width:'100%', height:40, border:'1.5px solid var(--border)', borderRadius:8, padding:'0 12px', background:'var(--bg)', color:'var(--text)', fontSize:14, outline:'none', fontFamily:'inherit', transition:'all .2s' };
  const focusEvt = (e: React.FocusEvent<HTMLInputElement | HTMLSelectElement>) => { e.target.style.borderColor='var(--pri)'; };
  const blurEvt = (e: React.FocusEvent<HTMLInputElement | HTMLSelectElement>) => { e.target.style.borderColor='var(--border)'; };

  const STAT_CARDS = [
    { label:'Tổng bài viết', num:(stats?.totalPosts??posts.length*47).toLocaleString(), icon:'📝', color:'var(--pri)' },
    { label:'Tổng người dùng', num:(stats?.totalUsers??users.length*23).toLocaleString(), icon:'👥', color:'var(--sec)' },
    { label:'Bình luận', num:(stats?.totalComments??posts.reduce((a,b)=>a+b.commentCount,0)*12).toLocaleString(), icon:'💬', color:'var(--acc)' },
    { label:'Hoạt động hôm nay', num:(stats?.activeUsers24h??38).toString(), icon:'🔥', color:'var(--warn)' },
  ];

  return (
    <div style={{ display:'flex', minHeight:'100vh', background:'var(--bg)' }}>
      {/* Sidebar */}
      <div style={{ width:240, background:'var(--surface)', borderRight:'1px solid var(--border)', flexShrink:0, display:'flex', flexDirection:'column' }}>
        <div style={{ padding:'20px 20px 10px', fontFamily:"'Syne',sans-serif", fontWeight:800, fontSize:18, background:'linear-gradient(135deg,var(--pri),var(--sec))', WebkitBackgroundClip:'text', WebkitTextFillColor:'transparent', backgroundClip:'text' }}>
          📚 Admin Panel
        </div>
        <div style={{ padding:'8px 10px', flex:1 }}>
          {MENU.map(m => (
            <button key={m.key} onClick={() => setMenu(m.key)}
              style={{ display:'flex', alignItems:'center', gap:10, padding:'10px 12px', borderRadius:8, cursor:'pointer', fontSize:14, fontWeight:500, color:menu===m.key?'var(--pri)':'var(--muted)', background:menu===m.key?'rgba(79,140,255,.1)':'transparent', border:'none', width:'100%', textAlign:'left', fontFamily:'inherit', transition:'all .15s', marginBottom:2 }}>
              <span>{m.icon}</span>{m.label}
            </button>
          ))}
        </div>
        <div style={{ padding:10, borderTop:'1px solid var(--border)' }}>
          <button onClick={() => navigate('/')} style={{ display:'flex', alignItems:'center', gap:8, padding:'10px 12px', width:'100%', borderRadius:8, border:'none', background:'transparent', color:'var(--muted)', cursor:'pointer', fontSize:14, fontFamily:'inherit' }}>
            ← Về diễn đàn
          </button>
        </div>
      </div>

      {/* Main */}
      <div style={{ flex:1, display:'flex', flexDirection:'column', overflow:'hidden' }}>
        {/* Header */}
        <div style={{ height:64, background:'var(--surface)', borderBottom:'1px solid var(--border)', display:'flex', alignItems:'center', padding:'0 32px', gap:16 }}>
          <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:18 }}>
            {MENU.find(m => m.key===menu)?.icon} {MENU.find(m => m.key===menu)?.label}
          </div>
          <div style={{ marginLeft:'auto', display:'flex', alignItems:'center', gap:10 }}>
            <UserAvatar user={currentUser} size="sm" />
            <span style={{ fontSize:14, fontWeight:500 }}>{currentUser.name}</span>
          </div>
        </div>

        <div style={{ flex:1, overflowY:'auto', padding:32 }}>

          {/* DASHBOARD */}
          {menu==='dashboard' && (
            <>
              <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit,minmax(200px,1fr))', gap:18, marginBottom:28 }}>
                {STAT_CARDS.map((s,i) => (
                  <div key={i} style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:'20px 24px' }}>
                    <div style={{ float:'right', fontSize:36, opacity:.15 }}>{s.icon}</div>
                    <div style={{ fontFamily:"'Syne',sans-serif", fontSize:32, fontWeight:800, color:s.color }}>{s.num}</div>
                    <div style={{ fontSize:14, color:'var(--muted)', marginTop:4 }}>{s.label}</div>
                  </div>
                ))}
              </div>

              <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:20, marginBottom:24 }}>
                {/* Bar chart */}
                <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:24 }}>
                  <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:15, marginBottom:18 }}>📈 Bài viết theo ngày (tuần này)</div>
                  <div style={{ display:'flex', alignItems:'flex-end', gap:10, height:120, paddingTop:8 }}>
                    {barData.map(d => (
                      <div key={d.l} style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:4 }}>
                        <div style={{ width:'100%', background:'linear-gradient(180deg,var(--pri),var(--sec))', borderRadius:'4px 4px 0 0', height:`${(d.v/maxBar)*90}px`, minHeight:4, transition:'height .4s' }} />
                        <div style={{ fontSize:11, color:'var(--faint)' }}>{d.l}</div>
                        <div style={{ fontSize:11, color:'var(--pri)', fontWeight:600 }}>{d.v}</div>
                      </div>
                    ))}
                  </div>
                </div>
                {/* Progress bars */}
                <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:24 }}>
                  <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:15, marginBottom:18 }}>📊 Thống kê hệ thống</div>
                  {[
                    { label:'Bài viết có câu trả lời', val:78 },
                    { label:'Người dùng hoạt động (7 ngày)', val:65 },
                    { label:'Tỷ lệ sinh viên', val:82 },
                    { label:'Mức độ hài lòng', val:91 },
                  ].map((s,i) => (
                    <div key={i} style={{ marginBottom:14 }}>
                      <div style={{ display:'flex', justifyContent:'space-between', fontSize:13, marginBottom:5 }}>
                        <span style={{ color:'var(--muted)' }}>{s.label}</span>
                        <span style={{ fontWeight:700, color:'var(--pri)' }}>{s.val}%</span>
                      </div>
                      <div style={{ height:6, borderRadius:3, background:'var(--border)', overflow:'hidden' }}>
                        <div style={{ height:'100%', width:`${s.val}%`, background:'linear-gradient(90deg,var(--pri),var(--sec))', borderRadius:3, transition:'width .4s' }} />
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Recent posts table */}
              <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:24 }}>
                <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:15, marginBottom:18 }}>📋 Bài viết gần đây</div>
                <table style={{ width:'100%', borderCollapse:'collapse' }}>
                  <thead>
                    <tr>{['Tiêu đề','Tác giả','Vote','Views','Ngày đăng'].map(h => (
                      <th key={h} style={{ background:'var(--bg)', padding:'10px 14px', textAlign:'left', fontSize:12, fontWeight:700, color:'var(--muted)', textTransform:'uppercase', letterSpacing:'.5px', borderBottom:'1px solid var(--border)' }}>{h}</th>
                    ))}</tr>
                  </thead>
                  <tbody>
                    {posts.slice(0,5).map(p => (
                      <tr key={p.id} style={{ cursor:'pointer' }} onClick={() => history.push(`/forum/${p.id}`)}>
                        <td style={{ padding:'13px 14px', borderBottom:'1px solid var(--border)', maxWidth:260, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', fontSize:14, color:'var(--pri)', fontWeight:500 }}>{p.title}</td>
                        <td style={{ padding:'13px 14px', borderBottom:'1px solid var(--border)', fontSize:14 }}>
                          <div style={{ display:'flex', alignItems:'center', gap:8 }}><UserAvatar user={p.author} size="sm" />{p.author.name}</div>
                        </td>
                        <td style={{ padding:'13px 14px', borderBottom:'1px solid var(--border)' }}><span style={{ background:'rgba(79,140,255,.1)', color:'var(--pri)', borderRadius:12, padding:'2px 10px', fontSize:13, fontWeight:600 }}>▲ {p.votes}</span></td>
                        <td style={{ padding:'13px 14px', borderBottom:'1px solid var(--border)', fontSize:14, color:'var(--muted)' }}>{p.views}</td>
                        <td style={{ padding:'13px 14px', borderBottom:'1px solid var(--border)', fontSize:13, color:'var(--faint)' }}>{timeAgo(p.createdAt)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </>
          )}

          {/* USERS */}
          {menu==='users' && (
            <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:24 }}>
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:20 }}>
                <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:17 }}>👥 Người dùng ({users.length})</div>
                <button onClick={() => setShowAddUser(true)} style={{ padding:'8px 20px', borderRadius:20, border:'none', background:'linear-gradient(135deg,var(--pri),var(--sec))', color:'#fff', cursor:'pointer', fontSize:13, fontWeight:500, fontFamily:'inherit' }}>+ Thêm người dùng</button>
              </div>
              <div style={{ overflowX:'auto' }}>
                <table style={{ width:'100%', borderCollapse:'collapse', minWidth:700 }}>
                  <thead>
                    <tr>{['Người dùng','Email','Vai trò','Trạng thái','Hành động'].map(h => (
                      <th key={h} style={{ background:'var(--bg)', padding:'10px 14px', textAlign:'left', fontSize:12, fontWeight:700, color:'var(--muted)', textTransform:'uppercase', letterSpacing:'.5px', borderBottom:'1px solid var(--border)' }}>{h}</th>
                    ))}</tr>
                  </thead>
                  <tbody>
                    {users.map(u => (
                      <tr key={u.id} onMouseEnter={e => (e.currentTarget.style.background='var(--bg)')} onMouseLeave={e => (e.currentTarget.style.background='transparent')}>
                        <td style={{ padding:'13px 14px', borderBottom:'1px solid var(--border)' }}>
                          <div style={{ display:'flex', alignItems:'center', gap:10 }}><UserAvatar user={u} size="sm" /><span style={{ fontWeight:500, fontSize:14 }}>{u.name}</span></div>
                        </td>
                        <td style={{ padding:'13px 14px', borderBottom:'1px solid var(--border)', fontSize:14, color:'var(--muted)' }}>{u.email}</td>
                        <td style={{ padding:'13px 14px', borderBottom:'1px solid var(--border)' }}><RoleBadge role={u.role} /></td>
                        <td style={{ padding:'13px 14px', borderBottom:'1px solid var(--border)' }}>
                          <span style={{ background:u.status==='active'?'rgba(34,197,94,.1)':'rgba(239,68,68,.1)', color:u.status==='active'?'var(--success)':'var(--danger)', borderRadius:12, padding:'3px 10px', fontSize:12, fontWeight:600 }}>
                            {u.status === 'active' ? '✓ Hoạt động' : '✗ Đã khóa'}
                          </span>
                        </td>
                        <td style={{ padding:'13px 14px', borderBottom:'1px solid var(--border)' }}>
                          <div style={{ display:'flex', gap:6 }}>
                            {[
                              { label:'Sửa', action:() => setEditUser(u), color:'var(--pri)' },
                              { label:u.status==='active'?'🔒 Khóa':'🔓 Mở', action:() => handleToggleLock(u.id), color:'var(--warn)' },
                              { label:'🔑 Reset', action:() => handleResetPw(u.id), color:'var(--muted)' },
                              ...(u.role!=='admin'?[{ label:'Xóa', action:() => handleDeleteUser(u.id), color:'var(--danger)' }]:[]),
                            ].map((btn,i) => (
                              <button key={i} onClick={btn.action} style={{ padding:'5px 12px', borderRadius:16, border:`1px solid ${btn.color}30`, background:`${btn.color}10`, color:btn.color, cursor:'pointer', fontSize:12, fontWeight:500, fontFamily:'inherit' }}>{btn.label}</button>
                            ))}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* POSTS */}
          {menu==='posts' && (
            <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:24 }}>
              <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:17, marginBottom:20 }}>📝 Bài viết ({posts.length})</div>
              <div style={{ overflowX:'auto' }}>
                <table style={{ width:'100%', borderCollapse:'collapse', minWidth:750 }}>
                  <thead>
                    <tr>{['Tiêu đề','Tác giả','Tags','Vote','Views','Ngày đăng','Hành động'].map(h => (
                      <th key={h} style={{ background:'var(--bg)', padding:'10px 14px', textAlign:'left', fontSize:12, fontWeight:700, color:'var(--muted)', textTransform:'uppercase', letterSpacing:'.5px', borderBottom:'1px solid var(--border)' }}>{h}</th>
                    ))}</tr>
                  </thead>
                  <tbody>
                    {posts.map(p => (
                      <tr key={p.id} onMouseEnter={e => (e.currentTarget.style.background='var(--bg)')} onMouseLeave={e => (e.currentTarget.style.background='transparent')}>
                        <td style={{ padding:'12px 14px', borderBottom:'1px solid var(--border)', maxWidth:220 }}>
                          <div style={{ overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', fontSize:14, fontWeight:500, color:'var(--pri)', cursor:'pointer' }} onClick={() => history.push(`/forum/${p.id}`)}>{p.title}</div>
                        </td>
                        <td style={{ padding:'12px 14px', borderBottom:'1px solid var(--border)', fontSize:14 }}>{p.author.name}</td>
                        <td style={{ padding:'12px 14px', borderBottom:'1px solid var(--border)' }}>
                          <div style={{ display:'flex', gap:4, flexWrap:'wrap' }}>
                            {p.tags.slice(0,2).map(t => <TagBadge key={t.id} tag={t} />)}
                            {p.tags.length>2 && <span style={{ fontSize:12, color:'var(--faint)' }}>+{p.tags.length-2}</span>}
                          </div>
                        </td>
                        <td style={{ padding:'12px 14px', borderBottom:'1px solid var(--border)' }}><span style={{ background:'rgba(79,140,255,.1)', color:'var(--pri)', borderRadius:12, padding:'2px 10px', fontSize:13, fontWeight:600 }}>▲ {p.votes}</span></td>
                        <td style={{ padding:'12px 14px', borderBottom:'1px solid var(--border)', fontSize:14, color:'var(--muted)' }}>{p.views}</td>
                        <td style={{ padding:'12px 14px', borderBottom:'1px solid var(--border)', fontSize:13, color:'var(--faint)' }}>{timeAgo(p.createdAt)}</td>
                        <td style={{ padding:'12px 14px', borderBottom:'1px solid var(--border)' }}>
                          <div style={{ display:'flex', gap:6 }}>
                            <button onClick={() => history.push(`/forum/${p.id}`)} style={{ padding:'5px 12px', borderRadius:16, border:'1px solid var(--border)', background:'transparent', color:'var(--muted)', cursor:'pointer', fontSize:12, fontFamily:'inherit' }}>Xem</button>
                            <button onClick={() => handleDeletePost(p.id)} style={{ padding:'5px 12px', borderRadius:16, border:'1px solid var(--danger)30', background:'rgba(239,68,68,.08)', color:'var(--danger)', cursor:'pointer', fontSize:12, fontFamily:'inherit' }}>Xóa</button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* TAGS */}
          {menu==='tags' && (
            <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:24 }}>
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:20 }}>
                <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:17 }}>🏷️ Quản lý Tags</div>
                <button onClick={() => setShowAddTag(true)} style={{ padding:'8px 20px', borderRadius:20, border:'none', background:'linear-gradient(135deg,var(--pri),var(--sec))', color:'#fff', cursor:'pointer', fontSize:13, fontWeight:500, fontFamily:'inherit' }}>+ Thêm tag</button>
              </div>
              <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(210px,1fr))', gap:14 }}>
                {[
                  {id:1,name:'Lập trình',color:'#4f8cff',usageCount:45},
                  {id:2,name:'Thuật toán',color:'#7b61ff',usageCount:32},
                  {id:3,name:'Cơ sở dữ liệu',color:'#4de2e2',usageCount:28},
                  {id:4,name:'SQL',color:'#ff6b6b',usageCount:21},
                  {id:5,name:'React',color:'#61dafb',usageCount:19},
                  {id:6,name:'Git',color:'#f05032',usageCount:38},
                ].map(t => (
                  <div key={t.id} style={{ border:'1px solid var(--border)', borderRadius:10, padding:18 }}>
                    <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:10 }}>
                      <TagBadge tag={t} />
                      <button onClick={async () => { if(window.confirm('Xóa tag này?')) { try { await adminService.deleteTag(t.id); addToast('Đã xóa tag','success'); } catch { addToast('Lỗi xóa','error'); } } }}
                        style={{ border:'none', background:'transparent', color:'var(--faint)', cursor:'pointer', fontSize:16, padding:2 }}>✕</button>
                    </div>
                    <div style={{ fontSize:13, color:'var(--muted)', marginBottom:8 }}>{t.usageCount} bài viết</div>
                    <div style={{ height:5, borderRadius:3, background:'var(--border)', overflow:'hidden' }}>
                      <div style={{ height:'100%', width:`${Math.min(100,(t.usageCount/50)*100)}%`, background:t.color, borderRadius:3 }} />
                    </div>
                  </div>
                ))}
                <div onClick={() => setShowAddTag(true)} style={{ border:'2px dashed var(--border)', borderRadius:10, padding:18, display:'flex', alignItems:'center', justifyContent:'center', flexDirection:'column', gap:8, cursor:'pointer', color:'var(--muted)', transition:'all .2s' }}
                  onMouseEnter={e => { (e.currentTarget as any).style.borderColor='var(--pri)'; (e.currentTarget as any).style.color='var(--pri)'; }}
                  onMouseLeave={e => { (e.currentTarget as any).style.borderColor='var(--border)'; (e.currentTarget as any).style.color='var(--muted)'; }}>
                  <span style={{ fontSize:28 }}>+</span>
                  <span style={{ fontSize:13 }}>Thêm tag mới</span>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* ── Modals ── */}
      {/* Edit User Modal */}
      {editUser && (
        <div style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.5)', zIndex:1000, display:'flex', alignItems:'center', justifyContent:'center', padding:24, backdropFilter:'blur(4px)' }} onClick={e => e.target===e.currentTarget&&setEditUser(null)}>
          <div style={{ background:'var(--surface)', borderRadius:20, padding:32, width:'100%', maxWidth:440, boxShadow:'var(--shadow-xl)' }}>
            <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:20, marginBottom:24 }}>✏️ Sửa người dùng: {editUser.name}</div>
            <div style={{ marginBottom:16 }}>
              <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:6 }}>Vai trò</label>
              <select value={editUser.role} onChange={e => setEditUser({...editUser,role:e.target.value as any})} style={{ ...inp, cursor:'pointer' }} onFocus={focusEvt} onBlur={blurEvt}>
                <option value="student">Sinh viên</option>
                <option value="lecturer">Giảng viên</option>
                <option value="admin">Quản trị viên</option>
              </select>
            </div>
            <div style={{ marginBottom:20, display:'flex', alignItems:'center', gap:10 }}>
              <input type="checkbox" checked={editUser.status === 'active'} onChange={e => setEditUser({...editUser, status: e.target.checked ? 'active' : 'locked'})} style={{ width:18, height:18, accentColor:'var(--pri)', cursor:'pointer' }} />
              <span style={{ fontSize:14 }}>Tài khoản đang hoạt động</span>
            </div>
            <div style={{ display:'flex', gap:10, justifyContent:'flex-end' }}>
              <button onClick={() => setEditUser(null)} style={{ padding:'9px 22px', borderRadius:20, border:'1.5px solid var(--border)', background:'transparent', color:'var(--muted)', cursor:'pointer', fontSize:14, fontFamily:'inherit' }}>Hủy</button>
              <button onClick={handleSaveUser} style={{ padding:'9px 22px', borderRadius:20, border:'none', background:'linear-gradient(135deg,var(--pri),var(--sec))', color:'#fff', cursor:'pointer', fontSize:14, fontWeight:500, fontFamily:'inherit' }}>Lưu thay đổi</button>
            </div>
          </div>
        </div>
      )}

      {/* Add User Modal */}
      {showAddUser && (
        <div style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.5)', zIndex:1000, display:'flex', alignItems:'center', justifyContent:'center', padding:24, backdropFilter:'blur(4px)' }} onClick={e => e.target===e.currentTarget&&setShowAddUser(false)}>
          <div style={{ background:'var(--surface)', borderRadius:20, padding:32, width:'100%', maxWidth:440, boxShadow:'var(--shadow-xl)' }}>
            <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:20, marginBottom:24 }}>➕ Thêm người dùng mới</div>
            {[{key:'name',label:'Tên người dùng',type:'text',ph:'Tên đầy đủ'},{key:'email',label:'Email',type:'email',ph:'email@student.edu.vn'},{key:'password',label:'Mật khẩu tạm',type:'password',ph:'Mật khẩu ban đầu'}].map(f => (
              <div key={f.key} style={{ marginBottom:16 }}>
                <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:6 }}>{f.label}</label>
                <input type={f.type} value={(newUser as any)[f.key]} onChange={e => setNewUser(p => ({...p,[f.key]:e.target.value}))} placeholder={f.ph} style={inp} onFocus={focusEvt} onBlur={blurEvt} />
              </div>
            ))}
            <div style={{ marginBottom:20 }}>
              <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:6 }}>Vai trò</label>
              <select value={newUser.role} onChange={e => setNewUser(p => ({...p,role:e.target.value}))} style={{ ...inp, cursor:'pointer' }} onFocus={focusEvt} onBlur={blurEvt}>
                <option value="student">Sinh viên</option>
                <option value="lecturer">Giảng viên</option>
                <option value="admin">Quản trị viên</option>
              </select>
            </div>
            <div style={{ display:'flex', gap:10, justifyContent:'flex-end' }}>
              <button onClick={() => setShowAddUser(false)} style={{ padding:'9px 22px', borderRadius:20, border:'1.5px solid var(--border)', background:'transparent', color:'var(--muted)', cursor:'pointer', fontSize:14, fontFamily:'inherit' }}>Hủy</button>
              <button onClick={handleAddUser} style={{ padding:'9px 22px', borderRadius:20, border:'none', background:'linear-gradient(135deg,var(--pri),var(--sec))', color:'#fff', cursor:'pointer', fontSize:14, fontWeight:500, fontFamily:'inherit' }}>Thêm người dùng</button>
            </div>
          </div>
        </div>
      )}

      {/* Add Tag Modal */}
      {showAddTag && (
        <div style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.5)', zIndex:1000, display:'flex', alignItems:'center', justifyContent:'center', padding:24, backdropFilter:'blur(4px)' }} onClick={e => e.target===e.currentTarget&&setShowAddTag(false)}>
          <div style={{ background:'var(--surface)', borderRadius:20, padding:32, width:'100%', maxWidth:400, boxShadow:'var(--shadow-xl)' }}>
            <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:20, marginBottom:24 }}>🏷️ Thêm Tag mới</div>
            <div style={{ marginBottom:16 }}>
              <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:6 }}>Tên tag</label>
              <input value={newTag.name} onChange={e => setNewTag(p => ({...p,name:e.target.value}))} placeholder="VD: Lập trình" style={inp} onFocus={focusEvt} onBlur={blurEvt} />
            </div>
            <div style={{ marginBottom:16 }}>
              <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:6 }}>Màu sắc</label>
              <div style={{ display:'flex', alignItems:'center', gap:12 }}>
                <input type="color" value={newTag.color} onChange={e => setNewTag(p => ({...p,color:e.target.value}))} style={{ width:50, height:42, border:'1.5px solid var(--border)', borderRadius:8, cursor:'pointer', background:'transparent' }} />
                <TagBadge tag={{name:newTag.name||'Tag mới',color:newTag.color}} />
              </div>
            </div>
            <div style={{ marginBottom:22 }}>
              <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:6 }}>Mô tả (tùy chọn)</label>
              <input value={newTag.description} onChange={e => setNewTag(p => ({...p,description:e.target.value}))} placeholder="Mô tả ngắn về tag này..." style={inp} onFocus={focusEvt} onBlur={blurEvt} />
            </div>
            <div style={{ display:'flex', gap:10, justifyContent:'flex-end' }}>
              <button onClick={() => setShowAddTag(false)} style={{ padding:'9px 22px', borderRadius:20, border:'1.5px solid var(--border)', background:'transparent', color:'var(--muted)', cursor:'pointer', fontSize:14, fontFamily:'inherit' }}>Hủy</button>
              <button onClick={async () => { if(!newTag.name){addToast('Nhập tên tag','error');return;} try { await adminService.createTag(newTag); setShowAddTag(false); setNewTag({name:'',color:'#4f8cff',description:''}); addToast('Đã thêm tag!','success'); } catch { addToast('Lỗi thêm tag','error'); } }} style={{ padding:'9px 22px', borderRadius:20, border:'none', background:'linear-gradient(135deg,var(--pri),var(--sec))', color:'#fff', cursor:'pointer', fontSize:14, fontWeight:500, fontFamily:'inherit' }}>
                Thêm tag
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminPage;

forum/index.__content:
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'umi';
import PostCard from '../../components/forum/PostCard';
import TagBadge from '../../components/common/TagBadge';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import EmptyState from '../../components/common/EmptyState';
import { forumService } from '../../services/forumService';
import type { Post, Tag, SortOption, User } from '../../types';

interface Props { currentUser: User | null; }

const SORT_OPTIONS: { key: SortOption; label: string }[] = [
  { key: 'newest', label: 'Mới nhất' },
  { key: 'hot', label: '🔥 Nổi bật' },
  { key: 'votes', label: '▲ Vote cao' },
  { key: 'views', label: '👁 Xem nhiều' },
];

const ForumPage: React.FC<Props> = ({ currentUser }) => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const initKeyword = searchParams.get('keyword') ?? '';
  const initTag = searchParams.get('tag') ?? null;

  const [posts, setPosts] = useState<Post[]>([]);
  const [tags, setTags] = useState<Tag[]>([]);
  const [loading, setLoading] = useState(true);
  const [sort, setSort] = useState<SortOption>('newest');
  const [keyword, setKeyword] = useState(initKeyword);
  const [activeTag, setActiveTag] = useState<string | null>(initTag);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [total, setTotal] = useState(0);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      try {
        const [pr, tr] = await Promise.all([
          forumService.getPosts({ page, sort, tag: activeTag ?? undefined, keyword: keyword || undefined, limit: 10 }),
          forumService.getTopTags(15),
        ]);
        setPosts(pr.data);
        setTotalPages(pr.pagination.totalPages);
        setTotal(pr.pagination.total);
        setTags(tr);
      } catch { /* empty */ }
      finally { setLoading(false); }
    };
    load();
  }, [page, sort, activeTag, keyword]);

  const inp: React.CSSProperties = {
    width:'100%', height:44, border:'1.5px solid var(--border)', borderRadius:8,
    padding:'0 14px', background:'var(--bg)', color:'var(--text)', fontSize:14,
    outline:'none', fontFamily:'inherit', transition:'all .2s',
  };

  return (
    <div style={{ maxWidth:1280, margin:'0 auto', padding:'32px 24px' }}>
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:24, flexWrap:'wrap', gap:12 }}>
        <div>
          <h1 style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:28, marginBottom:4 }}>📝 Diễn đàn thảo luận</h1>
          {total > 0 && <div style={{ fontSize:14, color:'var(--muted)' }}>{total.toLocaleString()} bài viết</div>}
        </div>
        {currentUser && (
          <button onClick={() => navigate('/ask')} style={{ display:'inline-flex',alignItems:'center',gap:6,padding:'0 20px',height:42,borderRadius:21,fontSize:14,fontWeight:600,cursor:'pointer',border:'none',background:'linear-gradient(135deg,var(--pri),var(--sec))',color:'#fff',fontFamily:'inherit' }}>
            ✏️ Đặt câu hỏi mới
          </button>
        )}
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 280px', gap:28, alignItems:'start' }}>
        {/* Main */}
        <div>
          {/* Search & sort */}
          <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:16, marginBottom:20 }}>
            <div style={{ position:'relative', marginBottom:14 }}>
              <span style={{ position:'absolute', left:12, top:'50%', transform:'translateY(-50%)', color:'var(--faint)', fontSize:15, pointerEvents:'none' }}>🔍</span>
              <input value={keyword} onChange={e => { setKeyword(e.target.value); setPage(1); }} placeholder="Tìm kiếm theo từ khóa..."
                style={{ ...inp, paddingLeft:38 }}
                onFocus={e => { e.target.style.borderColor='var(--pri)'; e.target.style.boxShadow='0 0 0 3px rgba(79,140,255,.1)'; }}
                onBlur={e => { e.target.style.borderColor='var(--border)'; e.target.style.boxShadow=''; }} />
            </div>
            <div style={{ display:'flex', gap:8, flexWrap:'wrap', alignItems:'center' }}>
              <span style={{ fontSize:13, color:'var(--muted)', fontWeight:500 }}>Sắp xếp:</span>
              {SORT_OPTIONS.map(s => (
                <button key={s.key} onClick={() => { setSort(s.key); setPage(1); }}
                  style={{ padding:'5px 14px', borderRadius:20, fontSize:13, fontWeight:500, cursor:'pointer', fontFamily:'inherit',
                    border:`1.5px solid ${sort===s.key?'var(--pri)':'var(--border)'}`,
                    background:sort===s.key?'rgba(79,140,255,.08)':'transparent',
                    color:sort===s.key?'var(--pri)':'var(--muted)', transition:'all .15s' }}>
                  {s.label}
                </button>
              ))}
              {activeTag && (
                <button onClick={() => { setActiveTag(null); setPage(1); }} style={{ padding:'5px 12px', borderRadius:20, fontSize:13, cursor:'pointer', border:'1.5px solid var(--danger)', color:'var(--danger)', background:'rgba(239,68,68,.06)', fontFamily:'inherit' }}>
                  ✕ #{activeTag}
                </button>
              )}
            </div>
          </div>

          {loading ? <LoadingSpinner /> : posts.length ? (
            <>
              <div style={{ display:'flex', flexDirection:'column', gap:14 }}>
                {posts.map(p => <PostCard key={p.id} post={p} />)}
              </div>
              {totalPages > 1 && (
                <div style={{ display:'flex', justifyContent:'center', gap:8, marginTop:28 }}>
                  <button disabled={page===1} onClick={() => setPage(p=>p-1)} style={{ padding:'8px 16px', borderRadius:8, border:'1.5px solid var(--border)', background:'transparent', color:'var(--muted)', cursor:page===1?'not-allowed':'pointer', opacity:page===1?.4:1, fontFamily:'inherit', fontSize:14 }}>← Trước</button>
                  {Array.from({length:Math.min(totalPages,7)},(_,i)=>i+1).map(p => (
                    <button key={p} onClick={() => setPage(p)} style={{ width:36, height:36, borderRadius:8, border:`1.5px solid ${page===p?'var(--pri)':'var(--border)'}`, background:page===p?'rgba(79,140,255,.08)':'transparent', color:page===p?'var(--pri)':'var(--muted)', cursor:'pointer', fontWeight:page===p?600:400, fontFamily:'inherit', fontSize:14 }}>{p}</button>
                  ))}
                  <button disabled={page===totalPages} onClick={() => setPage(p=>p+1)} style={{ padding:'8px 16px', borderRadius:8, border:'1.5px solid var(--border)', background:'transparent', color:'var(--muted)', cursor:page===totalPages?'not-allowed':'pointer', opacity:page===totalPages?.4:1, fontFamily:'inherit', fontSize:14 }}>Sau →</button>
                </div>
              )}
            </>
          ) : (
            <EmptyState icon="🔍" title="Không tìm thấy kết quả" description={keyword ? `Không có bài viết nào khớp với "${keyword}"` : 'Chưa có bài viết nào'} />
          )}
        </div>

        {/* Sidebar */}
        <div style={{ display:'flex', flexDirection:'column', gap:16, position:'sticky', top:80 }}>
          <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:18 }}>
            <div style={{ fontSize:12, fontWeight:700, letterSpacing:'.5px', color:'var(--muted)', textTransform:'uppercase', marginBottom:14 }}>🏷️ Lọc theo chủ đề</div>
            <div style={{ display:'flex', flexWrap:'wrap', gap:4 }}>
              {tags.map(t => (
                <TagBadge key={t.id} tag={t} active={activeTag===t.name}
                  onClick={() => { setActiveTag(activeTag===t.name?null:t.name); setPage(1); }} />
              ))}
            </div>
          </div>

          {currentUser && (
            <div style={{ background:'linear-gradient(135deg,var(--pri),var(--sec))', borderRadius:'var(--radius)', padding:20, textAlign:'center' }}>
              <div style={{ fontSize:24, marginBottom:8 }}>💡</div>
              <div style={{ color:'#fff', fontWeight:600, fontSize:15, marginBottom:6 }}>Có thắc mắc?</div>
              <div style={{ color:'rgba(255,255,255,.8)', fontSize:13, marginBottom:14 }}>Đặt câu hỏi và nhận câu trả lời từ cộng đồng!</div>
              <button onClick={() => history.push('/ask')} style={{ padding:'9px 22px', borderRadius:20, border:'none', background:'#fff', color:'var(--pri)', fontWeight:600, cursor:'pointer', fontSize:14, fontFamily:'inherit' }}>✏️ Đặt câu hỏi</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ForumPage;

auth/login.__content:
import React, { useState } from 'react';
import { useAuth } from '../../hooks/useAuth';

const LoginPage: React.FC = () => {
  const { login } = useAuth();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async () => {
    if (!email.trim() || !password) { setError('Vui lòng nhập đầy đủ thông tin'); return; }
    setLoading(true); setError('');
    try {
      await login({ email, password });
    } catch (e) { 
      const err = e as { response?: { data?: { message?: string } } };
      setError(err?.response?.data?.message || 'Email hoặc mật khẩu không chính xác');
    } finally { setLoading(false); }
  };

  const inp: React.CSSProperties = { width:'100%', height:46, border:'1.5px solid var(--border)', borderRadius:8, padding:'0 14px', background:'var(--bg)', color:'var(--text)', fontSize:15, outline:'none', fontFamily:'inherit', transition:'all .2s' };

  return (
    <div style={{ minHeight:'100vh', display:'flex', alignItems:'center', justifyContent:'center', padding:24, background:'linear-gradient(135deg,rgba(79,140,255,.06),rgba(123,97,255,.06))' }}>
      <div style={{ width:'100%', maxWidth:440, background:'var(--surface)', border:'1px solid var(--border)', borderRadius:20, padding:40, boxShadow:'var(--shadow-lg)' }}>
        <div style={{ textAlign:'center', marginBottom:32 }}>
          <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:800, fontSize:26, background:'linear-gradient(135deg,var(--pri),var(--sec))', WebkitBackgroundClip:'text', WebkitTextFillColor:'transparent', backgroundClip:'text', marginBottom:8 }}>📚 Diễn Đàn SV</div>
          <div style={{ color:'var(--muted)', fontSize:15 }}>Chào mừng trở lại!</div>
        </div>

        {error && (
          <div style={{ background:'rgba(239,68,68,.08)', border:'1px solid rgba(239,68,68,.3)', borderRadius:8, padding:'10px 14px', fontSize:14, color:'var(--danger)', marginBottom:18 }}>⚠️ {error}</div>
        )}

        <div style={{ marginBottom:18 }}>
          <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:6 }}>Email hoặc tên đăng nhập</label>
          <input value={email} onChange={e => setEmail(e.target.value)} onKeyDown={e => e.key==='Enter'&&handleSubmit()} placeholder="email@student.edu.vn" style={inp}
            onFocus={e => { e.target.style.borderColor='var(--pri)'; e.target.style.boxShadow='0 0 0 3px rgba(79,140,255,.1)'; }}
            onBlur={e => { e.target.style.borderColor='var(--border)'; e.target.style.boxShadow=''; }} />
        </div>

        <div style={{ marginBottom:24 }}>
          <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:6 }}>Mật khẩu</label>
          <input type="password" value={password} onChange={e => setPassword(e.target.value)} onKeyDown={e => e.key==='Enter'&&handleSubmit()} placeholder="••••••••" style={inp}
            onFocus={e => { e.target.style.borderColor='var(--pri)'; e.target.style.boxShadow='0 0 0 3px rgba(79,140,255,.1)'; }}
            onBlur={e => { e.target.style.borderColor='var(--border)'; e.target.style.boxShadow=''; }} />
        </div>

        <button onClick={handleSubmit} disabled={loading} style={{ width:'100%', height:48, borderRadius:24, border:'none', background:'linear-gradient(135deg,var(--pri),var(--sec))', color:'#fff', cursor:loading?'not-allowed':'pointer', fontSize:16, fontWeight:600, fontFamily:'inherit', opacity:loading?.75:1, transition:'all .2s' }}>
          {loading ? 'Đang đăng nhập...' : 'Đăng nhập →'}
        </button>

        <div style={{ display:'flex', alignItems:'center', gap:12, color:'var(--faint)', fontSize:13, margin:'20px 0' }}>
          <div style={{ flex:1, height:1, background:'var(--border)' }} />hoặc<div style={{ flex:1, height:1, background:'var(--border)' }} />
        </div>

        <div style={{ textAlign:'center', fontSize:14, color:'var(--muted)' }}>
          Chưa c
          <span onClick={() => window.location.href = '/auth/register'} style={{ color:'var(--pri)', fontWeight:600, cursor:'pointer' }}>Đăng ký ngay</span>
        </div>

        <div style={{ marginTop:20, padding:14, background:'var(--bg)', borderRadius:8, fontSize:13, color:'var(--faint)' }}>
          <strong>Demo:</strong> email bất kỳ / mật khẩu <code>123456</code>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;

forum/[id].__content:
import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'umi';
import UserAvatar from '../../components/common/UserAvatar';
import RoleBadge from '../../components/common/RoleBadge';
import TagBadge from '../../components/common/TagBadge';
import VoteButton from '../../components/forum/VoteButton';
import CommentItem from '../../components/forum/CommentItem';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import { forumService } from '../../services/forumService';
import { addToast } from '../../utils/toast';
import { timeAgo } from '../../utils/helpers';
import type { Post, Comment, User } from '../../types';

interface Props { currentUser: User | null; }

const PostDetailPage: React.FC<Props> = ({ currentUser }) => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const postId = id!;

  const [post, setPost] = useState<Post | null>(null);
  const [comments, setComments] = useState<Comment[]>([]);
  const [loading, setLoading] = useState(true);
  const [commentText, setCommentText] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [userVote, setUserVote] = useState<'up' | 'down' | null>(null);
  const [voteCount, setVoteCount] = useState(0);

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        const [p, c] = await Promise.all([
          forumService.getPost(postId),
          forumService.getComments(postId),
        ]);
        setPost(p);
        setVoteCount(p.votes || 0);
        setComments(c);
      } catch { addToast('Không tìm thấy bài viết', 'error'); navigate('/forum'); }
      finally { setLoading(false); }
    })();
  }, [postId, navigate]);

  const handleVote = async (direction: 'up' | 'down') => {
    if (!currentUser) { addToast('Vui lòng đăng nhập để vote', 'info'); navigate('/auth/login'); return; }
    const prevVote = userVote;
    const newVote = userVote === direction ? null : direction;
    setUserVote(newVote);
    try {
      await forumService.votePost(postId, direction);
      const p = await forumService.getPost(postId);
      setVoteCount(p.votes || 0);
    } catch {
      setUserVote(prevVote);
      addToast('Không thể cập nhật vote', 'error');
    }
  };

  const handleSave = async () => {
    if (!currentUser) { navigate('/auth/login'); return; }
    try {
      const r = await forumService.savePost(postId);
      setIsSaved(r.saved);
      addToast(r.saved ? 'Đã lưu bài viết!' : 'Đã bỏ lưu!', 'success');
    } catch { addToast('Lỗi thao tác', 'error'); }
  };

  const handleComment = async () => {
    if (!currentUser) { navigate('/auth/login'); return; }
    if (!commentText.trim()) { addToast('Vui lòng nhập nội dung', 'error'); return; }
    setSubmitting(true);
    try {
      const c = await forumService.createComment(postId, { content: commentText });
      setComments(prev => [c, ...prev]);
      setCommentText('');
      if (post) setPost({ ...post, commentCount: (post.commentCount || 0) + 1 });
      addToast('Đã thêm bình luận!', 'success');
    } catch { addToast('Không thể gửi bình luận', 'error'); }
    finally { setSubmitting(false); }
  };

  const handleDeleteComment = async (cid: string) => {
    if (!window.confirm('Xóa bình luận này?')) return;
    try {
      await forumService.deleteComment(cid);
      setComments(prev => prev.filter(c => c.id !== cid));
      addToast('Đã xóa bình luận', 'success');
    } catch { addToast('Không thể xóa', 'error'); }
  };

  const handleReplyAdded = (parentId: number, reply: Comment) => {
    setComments(prev => prev.map(c => c.id === parentId ? { ...c, replies: [...(c.replies ?? []), reply] } : c));
  };

  const handleDeletePost = async () => {
    if (!window.confirm('Xóa bài viết này? Hành động không thể hoàn tác!')) return;
    try {
      await forumService.deletePost(postId);
      addToast('Đã xóa bài viết', 'success');
      navigate('/forum');
    } catch { addToast('Không thể xóa', 'error'); }
  };

  if (loading) return <div style={{ maxWidth:960, margin:'0 auto', padding:'40px 24px' }}><LoadingSpinner /></div>;
  if (!post) return null;

  const canEdit = currentUser && (currentUser.id === post.authorId || currentUser.role === 'admin');
  const ta: React.CSSProperties = { width:'100%', minHeight:110, border:'1.5px solid var(--border)', borderRadius:8, padding:'10px 14px', background:'var(--bg)', color:'var(--text)', fontSize:14, fontFamily:'inherit', resize:'vertical', outline:'none', lineHeight:1.7 };

  return (
    <div style={{ maxWidth:1100, margin:'0 auto', padding:'32px 24px' }}>
      {/* Breadcrumb */}
      <div style={{ display:'flex', alignItems:'center', gap:6, fontSize:14, color:'var(--muted)', marginBottom:24, cursor:'pointer' }}
        onClick={() => navigate('/forum')}>
        ← Diễn đàn · <span style={{ color:'var(--text)', fontWeight:500, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap', maxWidth:400 }}>{post.title}</span>
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 280px', gap:28, alignItems:'start' }}>
        {/* Main content */}
        <div>
          {/* Post card */}
          <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:32, marginBottom:20 }}>
            {/* Author */}
            <div style={{ display:'flex', alignItems:'center', gap:10, marginBottom:20 }}>
              <UserAvatar user={post.author} size="md" />
              <div>
                <div style={{ display:'flex', alignItems:'center', gap:8, flexWrap:'wrap' }}>
                  <span style={{ fontWeight:600, fontSize:15 }}>{post.author.username}</span>
                  <RoleBadge role={post.author.role} />
                </div>
                <div style={{ fontSize:13, color:'var(--faint)', marginTop:2 }}>{timeAgo(post.createdAt)} · 👁 {post.views.toLocaleString()} lượt xem</div>
              </div>
              <div style={{ marginLeft:'auto', display:'flex', gap:8 }}>
                <button onClick={handleSave} title={isSaved?'Bỏ lưu':'Lưu bài'} style={{ padding:'6px 14px', borderRadius:20, border:`1.5px solid ${isSaved?'var(--warn)':'var(--border)'}`, background:isSaved?'rgba(245,158,11,.08)':'transparent', color:isSaved?'var(--warn)':'var(--muted)', cursor:'pointer', fontSize:13, fontFamily:'inherit' }}>
                  {isSaved ? '🔖 Đã lưu' : '🔖 Lưu'}
                </button>
                {canEdit && (
                  <>
                    <button onClick={() => navigate(`/ask?edit=${postId}`)} style={{ padding:'6px 14px', borderRadius:20, border:'1.5px solid var(--border)', background:'transparent', color:'var(--muted)', cursor:'pointer', fontSize:13, fontFamily:'inherit' }}>✏️ Sửa</button>
                    <button onClick={handleDeletePost} style={{ padding:'6px 14px', borderRadius:20, border:'1.5px solid var(--danger)', background:'rgba(239,68,68,.06)', color:'var(--danger)', cursor:'pointer', fontSize:13, fontFamily:'inherit' }}>🗑️ Xóa</button>
                  </>
                )}
              </div>
            </div>

            {/* Title */}
            <h1 style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:26, lineHeight:1.3, marginBottom:16 }}>{post.title}</h1>

            {/* Tags */}
            <div style={{ display:'flex', flexWrap:'wrap', gap:6, marginBottom:20 }}>
              {post.tags.map(t => <TagBadge key={t.id} tag={t} onClick={() => navigate(`/forum?tag=${t.name}`)} />)}
            </div>

            {/* Content + Vote */}
            <div style={{ display:'flex', gap:24 }}>
              <VoteButton votes={voteCount} userVote={userVote} onVote={handleVote} disabled={!currentUser} />
              <div style={{ flex:1, fontSize:15, lineHeight:1.8, color:'var(--text)', whiteSpace:'pre-wrap', wordBreak:'break-word' }}>
                {post.content}
              </div>
            </div>
          </div>

          {/* Comment form */}
          <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:24, marginBottom:20 }}>
            <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:17, marginBottom:16 }}>💬 Thêm bình luận</div>
            {currentUser ? (
              <>
                <div style={{ display:'flex', alignItems:'center', gap:10, marginBottom:12 }}>
                  <UserAvatar user={currentUser} size="sm" />
                  <span style={{ fontWeight:500, fontSize:14 }}>{currentUser.username}</span>
                </div>
                <textarea value={commentText} onChange={e => setCommentText(e.target.value)} placeholder="Chia sẻ suy nghĩ hoặc giải đáp câu hỏi..."
                  style={ta}
                  onFocus={e => { e.target.style.borderColor='var(--pri)'; e.target.style.boxShadow='0 0 0 3px rgba(79,140,255,.1)'; }}
                  onBlur={e => { e.target.style.borderColor='var(--border)'; e.target.style.boxShadow=''; }} />
                <div style={{ display:'flex', justifyContent:'flex-end', marginTop:12 }}>
                  <button onClick={handleComment} disabled={submitting} style={{ padding:'9px 24px', borderRadius:20, border:'none', background:'linear-gradient(135deg,var(--pri),var(--sec))', color:'#fff', cursor:submitting?'not-allowed':'pointer', fontSize:14, fontWeight:500, fontFamily:'inherit', opacity:submitting?.7:1 }}>
                    {submitting ? 'Đang gửi...' : '📤 Gửi bình luận'}
                  </button>
                </div>
              </>
            ) : (
              <div style={{ textAlign:'center', padding:'20px 0' }}>
                <p style={{ color:'var(--muted)', marginBottom:14 }}>Đăng nhập để tham gia thảo luận</p>
                <button onClick={() => navigate('/auth/login')} style={{ padding:'10px 28px', borderRadius:20, border:'none', background:'linear-gradient(135deg,var(--pri),var(--sec))', color:'#fff', cursor:'pointer', fontSize:14, fontWeight:500, fontFamily:'inherit' }}>Đăng nhập</button>
              </div>
            )}
          </div>

          {/* Comments list */}
          <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:24 }}>
            <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:17, marginBottom:20 }}>
              💬 {comments.length} bình luận
            </div>
            {comments.length ? (
              comments.map(c => (
                <CommentItem key={c.id} comment={c} postId={postId} currentUser={currentUser}
                  onDelete={handleDeleteComment} onReplyAdded={handleReplyAdded} />
              ))
            ) : (
              <div style={{ textAlign:'center', padding:'32px 0', color:'var(--muted)' }}>
                <div style={{ fontSize:36, marginBottom:10 }}>💭</div>
                <p>Chưa có bình luận nào. Hãy là người đầu tiên!</p>
              </div>
            )}
          </div>
        </div>

        {/* Sidebar */}
        <div style={{ display:'flex', flexDirection:'column', gap:16, position:'sticky', top:80 }}>
          <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:20 }}>
            <div style={{ fontSize:12, fontWeight:700, letterSpacing:'.5px', color:'var(--muted)', textTransform:'uppercase', marginBottom:14 }}>📌 Thông tin bài viết</div>
            {[
              { label:'Tác giả', val: post.author.username },
              { label:'Đăng lúc', val: timeAgo(post.createdAt) },
              { label:'Lượt xem', val: `👁 ${post.views.toLocaleString()}` },
              { label:'Vote', val: `▲ ${voteCount}` },
              { label:'Bình luận', val: `💬 ${comments.length}` },
            ].map((r,i) => (
              <div key={i} style={{ marginBottom:12 }}>
                <div style={{ fontSize:12, color:'var(--faint)', marginBottom:2 }}>{r.label}</div>
                <div style={{ fontWeight:500, fontSize:14 }}>{r.val}</div>
              </div>
            ))}
          </div>
          {post.tags.length > 0 && (
            <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:20 }}>
              <div style={{ fontSize:12, fontWeight:700, letterSpacing:'.5px', color:'var(--muted)', textTransform:'uppercase', marginBottom:12 }}>🏷️ Tags</div>
              <div style={{ display:'flex', flexWrap:'wrap', gap:6 }}>
                {post.tags.map(t => <TagBadge key={t.id} tag={t} onClick={() => navigate(`/forum?tag=${t.name}`)} />)}
              </div>
            </div>
          )}
          <button onClick={() => navigate('/forum')} style={{ padding:'11px 0', borderRadius:'var(--radius)', border:'1.5px solid var(--border)', background:'transparent', color:'var(--muted)', cursor:'pointer', fontSize:14, fontFamily:'inherit', transition:'all .2s' }}
            onMouseEnter={e => { const el = e.currentTarget as HTMLButtonElement; el.style.borderColor='var(--pri)'; el.style.color='var(--pri)'; }}
            onMouseLeave={e => { const el = e.currentTarget as HTMLButtonElement; el.style.borderColor='var(--border)'; el.style.color='var(--muted)'; }}>
            ← Về diễn đàn
          </button>
        </div>
      </div>
    </div>
  );
};

export default PostDetailPage;

profile.__content:
import React, { useState } from 'react';
import { useNavigate } from 'umi';
import UserAvatar from '../components/common/UserAvatar';
import RoleBadge from '../components/common/RoleBadge';
import { userService } from '../services/userService';
import { authService } from '../services/authService';
import { addToast } from '../utils/toast';
import type { User } from '../types';

interface Props { currentUser: User | null; onUpdateUser: (u: Partial<User>) => void; }

const ProfilePage: React.FC<Props> = ({ currentUser, onUpdateUser }) => {
  const navigate = useNavigate();
  const [tab, setTab] = useState<'posts'|'saved'|'edit'|'password'>('posts');
  const [form, setForm] = useState({ username: currentUser?.username||'', bio: currentUser?.bio||'', email: currentUser?.email||'' });
  const [pwForm, setPwForm] = useState({ current:'', newpw:'', confirm:'' });
  const [saving, setSaving] = useState(false);

  if (!currentUser) { navigate('/auth/login'); return null; }

  const inp: React.CSSProperties = { width:'100%', height:44, border:'1.5px solid var(--border)', borderRadius:8, padding:'0 14px', background:'var(--bg)', color:'var(--text)', fontSize:14, outline:'none', fontFamily:'inherit', transition:'all .2s' };
  const focus = (e: React.FocusEvent<HTMLInputElement>) => { e.target.style.borderColor='var(--pri)'; e.target.style.boxShadow='0 0 0 3px rgba(79,140,255,.1)'; };
  const blur = (e: React.FocusEvent<HTMLInputElement>) => { e.target.style.borderColor='var(--border)'; e.target.style.boxShadow=''; };

  const handleSaveProfile = async () => {
    setSaving(true);
    try {
      const updated = await userService.updateProfile(form);
      onUpdateUser(updated);
      addToast('Đã cập nhật hồ sơ!', 'success');
    } catch { addToast('Không thể cập nhật', 'error'); }
    finally { setSaving(false); }
  };

  const handleChangePw = async () => {
    if (!pwForm.current) { addToast('Nhập mật khẩu hiện tại', 'error'); return; }
    if (pwForm.newpw.length < 6) { addToast('Mật khẩu mới ít nhất 6 ký tự', 'error'); return; }
    if (pwForm.newpw !== pwForm.confirm) { addToast('Mật khẩu xác nhận không khớp', 'error'); return; }
    setSaving(true);
    try {
      await authService.changePassword(pwForm.current, pwForm.newpw);
      setPwForm({ current:'', newpw:'', confirm:'' });
      addToast('Đã đổi mật khẩu thành công!', 'success');
    } catch { addToast('Mật khẩu hiện tại không đúng', 'error'); }
    finally { setSaving(false); }
  };

  const TABS = [
    { key:'posts', label:'📝 Bài viết' },
    { key:'saved', label:'🔖 Đã lưu' },
    { key:'edit', label:'⚙️ Hồ sơ' },
    { key:'password', label:'🔒 Mật khẩu' },
  ];

  return (
    <div style={{ maxWidth:960, margin:'0 auto', padding:'32px 24px' }}>
      {/* Profile header */}
      <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:'28px 32px', marginBottom:24, display:'flex', alignItems:'flex-start', gap:24 }}>
        <div style={{ position:'relative' }}>
          <UserAvatar user={currentUser} size="xl" />
          <div
            title="Thay đổi ảnh"
            style={{ position:'absolute', bottom:4, right:4, width:28, height:28, borderRadius:'50%', background:'var(--pri)', color:'#fff', display:'flex', alignItems:'center', justifyContent:'center', cursor:'pointer', fontSize:14, border:'2px solid var(--surface)' }}
            onClick={async () => {
              const input = document.createElement('input'); input.type='file'; input.accept='image/*';
              input.onchange = async () => {
                if (input.files?.[0]) {
                  try { const r = await userService.uploadAvatar(input.files[0]); onUpdateUser({ avatar: r.avatar }); addToast('Đã cập nhật ảnh!', 'success'); }
                  catch { addToast('Không thể upload ảnh', 'error'); }
                }
              };
              input.click();
            }}>
            📷
          </div>
        </div>
        <div style={{ flex:1 }}>
          <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:800, fontSize:24, marginBottom:6 }}>{currentUser.username}</div>
          <div style={{ marginBottom:8 }}><RoleBadge role={currentUser.role} /></div>
          <div style={{ fontSize:14, color:'var(--muted)', marginBottom:12 }}>{currentUser.email}</div>
          {currentUser.bio && <div style={{ fontSize:14, color:'var(--text)', lineHeight:1.6 }}>{currentUser.bio}</div>}
          <div style={{ display:'flex', gap:28, marginTop:16 }}>
            {[{num:12,label:'Bài viết'},{num:48,label:'Bình luận'},{num:234,label:'Vote nhận'}].map((s,i) => (
              <div key={i}>
                <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:800, fontSize:22, color:'var(--pri)' }}>{s.num}</div>
                <div style={{ fontSize:13, color:'var(--muted)' }}>{s.label}</div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div style={{ display:'flex', borderBottom:'2px solid var(--border)', marginBottom:24 }}>
        {TABS.map(t => (
          <button key={t.key} onClick={() => setTab(t.key as any)}
            style={{ padding:'10px 20px', fontSize:14, fontWeight:500, color:tab===t.key?'var(--pri)':'var(--muted)', cursor:'pointer', border:'none', background:'transparent', borderBottom:`2px solid ${tab===t.key?'var(--pri)':'transparent'}`, marginBottom:-2, fontFamily:'inherit', transition:'all .15s' }}>
            {t.label}
          </button>
        ))}
      </div>

      {/* Tab: Posts */}
      {tab==='posts' && (
        <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:24 }}>
          <div style={{ textAlign:'center', padding:'40px 0', color:'var(--muted)' }}>
            <div style={{ fontSize:40, marginBottom:12 }}>📝</div>
            <p>Bạn chưa đăng bài viết nào</p>
            <button onClick={() => history.push('/ask')} style={{ marginTop:14, padding:'10px 24px', borderRadius:20, border:'none', background:'linear-gradient(135deg,var(--pri),var(--sec))', color:'#fff', cursor:'pointer', fontSize:14, fontWeight:500, fontFamily:'inherit' }}>Đặt câu hỏi đầu tiên</button>
          </div>
        </div>
      )}

      {/* Tab: Saved */}
      {tab==='saved' && (
        <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:24 }}>
          <div style={{ textAlign:'center', padding:'40px 0', color:'var(--muted)' }}>
            <div style={{ fontSize:40, marginBottom:12 }}>🔖</div>
            <p>Chưa có bài viết nào được lưu</p>
          </div>
        </div>
      )}

      {/* Tab: Edit profile */}
      {tab==='edit' && (
        <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:28, maxWidth:560 }}>
          <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:18, marginBottom:24 }}>Thông tin cá nhân</div>
          {[
            { key:'username', label:'Tên đăng nhập', type:'text' },
            { key:'email', label:'Email', type:'email' },
          ].map(field => (
            <div key={field.key} style={{ marginBottom:18 }}>
              <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:6 }}>{field.label}</label>
              <input type={field.type} value={(form as any)[field.key]} onChange={e => setForm(p => ({ ...p, [field.key]: e.target.value }))} style={inp} onFocus={focus} onBlur={blur} />
            </div>
          ))}
          <div style={{ marginBottom:24 }}>
            <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:6 }}>Giới thiệu bản thân</label>
            <textarea value={form.bio} onChange={e => setForm(p => ({ ...p, bio: e.target.value }))} placeholder="Mô tả ngắn về bản thân, chuyên ngành, sở thích..."
              style={{ width:'100%', minHeight:100, border:'1.5px solid var(--border)', borderRadius:8, padding:'10px 14px', background:'var(--bg)', color:'var(--text)', fontSize:14, fontFamily:'inherit', resize:'vertical', outline:'none', lineHeight:1.7 }}
              onFocus={focus} onBlur={blur} />
          </div>
          <button onClick={handleSaveProfile} disabled={saving} style={{ padding:'10px 28px', borderRadius:20, border:'none', background:'linear-gradient(135deg,var(--pri),var(--sec))', color:'#fff', cursor:saving?'not-allowed':'pointer', fontSize:14, fontWeight:600, fontFamily:'inherit', opacity:saving?.75:1 }}>
            {saving ? 'Đang lưu...' : '💾 Lưu thay đổi'}
          </button>
        </div>
      )}

      {/* Tab: Password */}
      {tab==='password' && (
        <div style={{ background:'var(--surface)', border:'1px solid var(--border)', borderRadius:'var(--radius)', padding:28, maxWidth:480 }}>
          <div style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:18, marginBottom:24 }}>Đổi mật khẩu</div>
          {[
            { key:'current', label:'Mật khẩu hiện tại', placeholder:'Nhập mật khẩu hiện tại' },
            { key:'newpw', label:'Mật khẩu mới', placeholder:'Ít nhất 6 ký tự' },
            { key:'confirm', label:'Xác nhận mật khẩu mới', placeholder:'Nhập lại mật khẩu mới' },
          ].map(field => (
            <div key={field.key} style={{ marginBottom:18 }}>
              <label style={{ display:'block', fontWeight:600, fontSize:14, marginBottom:6 }}>{field.label}</label>
              <input type="password" value={(pwForm as any)[field.key]} onChange={e => setPwForm(p => ({ ...p, [field.key]: e.target.value }))} placeholder={field.placeholder} style={inp} onFocus={focus} onBlur={blur} />
            </div>
          ))}
          <button onClick={handleChangePw} disabled={saving} style={{ padding:'10px 28px', borderRadius:20, border:'none', background:'linear-gradient(135deg,var(--pri),var(--sec))', color:'#fff', cursor:saving?'not-allowed':'pointer', fontSize:14, fontWeight:600, fontFamily:'inherit', opacity:saving?.75:1 }}>
            {saving ? 'Đang lưu...' : '🔒 Đổi mật khẩu'}
          </button>
        </div>
      )}
    </div>
  );
};

export default ProfilePage;

